/*
 * A228096  Numbers consisting of only odd digits such that no permutation of
 *          its digits yields a prime.
 * https://oeis.org/A228096
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) is the n-th integer composed only of odd digits such that
 *            every permutation of its decimal digits is composite. The
 *            sequence is generated by scanning odd‑digit numbers in
 *            increasing order and selecting those with the property above.
 *            This is a constructive algorithm, not expressed as a closed...
 * Range:     u8 n <= 13, u16 n <= 353, u32 n <= 511, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   digits_all_odd, is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdlib.h>
#include "../utils/is_prime_big.h"
#include "../utils/digits_all_odd.h"

/* Generate the next lexicographic permutation of an array a[0..len-1]
   of unsigned 8‑bit digits.  Return true if the array was altered
   (a next permutation exists) or false if it is already the last
   (descending) permutation.  This routine treats duplicate digits as
   separate elements, so equal permutations will re‑appear; the caller
   can ignore the repetitions. */
static bool next_permutation(uint8_t *a, int len)
{
    int i = len - 2;
    while (i >= 0 && a[i] >= a[i + 1]) i--;
    if (i < 0) return false;

    int j = len - 1;
    while (a[j] <= a[i]) j--;

    uint8_t tmp = a[i];
    a[i] = a[j];
    a[j] = tmp;

    for (int l = i + 1, r = len - 1; l < r; l++, r--) {
        tmp = a[l];
        a[l] = a[r];
        a[r] = tmp;
    }
    return true;
}

/* Return true iff some permutation of the decimal digits of n is a prime. */
static bool has_prime_permutation(idx_t n)
{
    uint8_t buf[20];
    int len = 0;
    idx_t t = n;
    do {
        buf[len++] = t % 10;
        t /= 10;
    } while (t != 0);

    /* Sort digits ascending to start permutations from the smallest arrangement */
    for (int i = 0; i < len; ++i)
        for (int j = i + 1; j < len; ++j)
            if (buf[i] > buf[j]) {
                uint8_t u = buf[i];
                buf[i] = buf[j];
                buf[j] = u;
            }

    do {
        idx_t v = 0;
        for (int i = 0; i < len; ++i)
            v = v * 10 + buf[i];
        if (is_prime_big((seq_t)v))
            return true;
    } while (next_permutation(buf, len));

    return false;
}

/* Return the n-th term of the sequence (1‑based index). */
seq_t a(idx_t n)
{
    /* Static cache for previously computed terms. */
    static seq_t *cache      = NULL;
    static size_t cache_sz   = 0;    /* number of terms stored */
    static size_t cache_cap  = 0;    /* capacity of cache array    */
    static idx_t next_candidate = 1; /* next integer to test      */

    /* Grow the cache until it contains at least n terms. */
    while (cache_sz < n) {
        /* Skip numbers that contain an even decimal digit. */
        while (!digits_all_odd(next_candidate))
            ++next_candidate;

        /* Check whether any permutation of this number is prime. */
        if (!has_prime_permutation(next_candidate)) {
            /* Ensure capacity. */
            if (cache_sz + 1 > cache_cap) {
                cache_cap = cache_cap ? cache_cap * 2 : 64;
                cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
            }
            /* Store the candidate. */
            cache[cache_sz++] = (seq_t)next_candidate;
        }
        ++next_candidate;
    }

    return cache[n - 1];
}
